INSERT INTO conceptos_ingresos (formulario,version,casilla,bloque,nombre,explicacion,fundamento,ejemplo,soportes,clase,formula) VALUES
('210','2026-10',99,'Pensiones','Ingresos brutos por rentas de pensiones del país y del exterior','Registra la pensión bruta antes de descuentos. Identifica mes, pagador y país. La exención se revisa separadamente, no se presume que toda pensión esté exenta.','ET 337 y 206.5; instructivo DIAN 210 casilla 99','Una mesada se registra en el mes de reconocimiento.','Certificado de pensiones y detalle de mesadas.','ingreso',''),
('210','2026-10',104,'Dividendos y participaciones','Dividendos y participaciones año 2016 y anteriores, y otros','El año de las utilidades es distinto del año en que recibes el dividendo. Usa la composición certificada por la sociedad y revisa los otros supuestos del instructivo.','ET 49 y 246-1; instructivo DIAN 210 casilla 104','Dividendo recibido este año con cargo a utilidades de 2016.','Certificado de dividendos, año de utilidades y acta de distribución.','ingreso',''),
('210','2026-10',107,'Dividendos y participaciones','1a. Subcédula años 2017 y siguientes numeral 3 art. 49 del E.T.','Usa el certificado que separa las utilidades según el numeral 3 del artículo 49. No mezcles este importe con la segunda subcédula ni con dividendos del exterior.','ET 49.3 y 242; instructivo DIAN 210 casilla 107','Registra solo el importe certificado para esta clasificación.','Certificado con origen, año de utilidades, tratamiento y retenciones.','ingreso',''),
('210','2026-10',108,'Dividendos y participaciones','2a. Subcédula años 2017 y siguientes parágrafo 2 art. 49 del E.T.','Registra el ingreso certificado de esta subcédula. La tarifa y depuración específica se revisan en análisis; el importe guardado no es una liquidación del impuesto.','ET 49 parágrafo 2 y 242; instructivo DIAN 210 casilla 108','Separa las utilidades gravadas de las correspondientes a la primera subcédula.','Certificado de dividendos con tratamiento y tarifa aplicable.','ingreso',''),
('210','2026-10',109,'Dividendos y participaciones','Dividendos y participaciones recibidas del exterior','Distingue dividendos del exterior y rentas pasivas ECE según el instructivo. No registres nuevamente rentas ya reconocidas; documenta fuente, conversión y convenios.','ET 882 a 893 y 242; instructivo DIAN 210 casilla 109','Dividendo extranjero convertido a pesos con soporte.','Certificado extranjero, conversión fiscal y análisis ECE cuando corresponda.','ingreso',''),
('210','2026-10',112,'Ganancias ocasionales','Ingresos por ganancias ocasionales del país y del exterior','Sección independiente de las cédulas. Registra el ingreso bruto que corresponda a venta de activo fijo poseído dos años o más, herencia, donación u otro supuesto legal. No registres solo la utilidad.','ET 299 a 317; instructivo DIAN 210 casilla 112','Venta de un activo fijo: ingreso y costo se revisan por separado.','Escritura, fecha y costo de adquisición, sucesión o certificado del hecho.','ingreso',''),
('110','2026-10',49,'Ingresos','Dividendos y participaciones no constitutivos de renta ni ganancia ocasional','Usa la clasificación certificada por la sociedad. Incluir aquí no autoriza restar de nuevo el mismo ingreso sin revisar la depuración del formulario.','ET 49; instructivo DIAN 110 casilla 49','Clasifica según el certificado, no solo según el nombre del pago.','Certificado de dividendos y composición de utilidades.','ingreso',''),
('110','2026-10',50,'Ingresos','Dividendos del exterior a una CHC y prima en colocación de acciones','Supuesto especial: verifica habilitación CHC y los requisitos de cada concepto. No es la casilla general para cualquier dividendo extranjero.','ET 898 y siguientes; instructivo DIAN 110 casilla 50','Revisa el supuesto especial antes de asignar el ingreso.','RUT, certificado y análisis de los requisitos del régimen.','ingreso',''),
('110','2026-10',51,'Ingresos','Dividendos gravados a tarifa general de sociedades extranjeras o nacionales','Clasifica el ingreso con la información fiscal del certificado. No duplicar los conceptos de la casilla 50 ni los que tengan otra clasificación específica.','ET 49 parágrafo 2; instructivo DIAN 110 casilla 51','Separa por origen y tratamiento certificado.','Certificado, origen y año de utilidades.','ingreso',''),
('110','2026-10',52,'Ingresos','Dividendos gravados de personas naturales no residentes: 2016 y anteriores','Exclusiva de persona natural no residente. El año de las utilidades no es el año de registro del ingreso.','ET 246-1; instructivo DIAN 110 casilla 52','Utilidades hasta 2016 distribuidas en el año seleccionado.','Certificado con año y naturaleza fiscal de las utilidades.','ingreso',''),
('110','2026-10',53,'Ingresos','Dividendos gravados de personas naturales no residentes: 2017 y siguientes','Exclusiva de persona natural no residente. Revisa exigibilidad y régimen de las utilidades antes de clasificar.','ET 245; instructivo DIAN 110 casilla 53','Utilidades desde 2017 reconocidas en el año seleccionado.','Certificado y acta de distribución.','ingreso',''),
('110','2026-10',54,'Ingresos','Dividendos gravados a las tarifas de los artículos 245 o 246 E.T.','Requiere revisar receptor, exigibilidad y origen de utilidades. La captura no asigna automáticamente una tarifa ni calcula retenciones.','ET 245 y 246; instructivo DIAN 110 casilla 54','Separa el supuesto certificado de las demás casillas.','Certificado de dividendos y condición fiscal del receptor.','ingreso',''),
('110','2026-10',55,'Ingresos','Dividendos a tarifa general: EP y sociedades extranjeras, utilidades desde 2017','Tratamiento especial de receptores del exterior y establecimientos permanentes. Verifica el supuesto y evita duplicación con otras casillas de dividendos.','ET 245 y 246; instructivo DIAN 110 casilla 55','Registra solo lo que corresponde al supuesto certificado.','Certificado, condición del receptor y análisis tributario.','ingreso',''),
('110','2026-10',56,'Ingresos','Dividendos de proyectos calificados como megainversión gravados al 27%','Supuesto especial sujeto a requisitos y transición legal. La existencia de esta casilla no demuestra que el contribuyente pueda aplicar el tratamiento.','Instructivo DIAN 110 casilla 56; revisar transición del ET 235-3','Exige evidencia de calificación y aplicabilidad temporal.','Certificación del proyecto y revisión de vigencia y requisitos.','ingreso',''),
('110','2026-10',80,'Ganancias ocasionales','Ingresos por ganancias ocasionales','Sección independiente de los ingresos ordinarios. Registra el ingreso bruto y documenta el supuesto legal; no equivale a la ganancia gravable final.','ET 299 a 317; instructivo DIAN 110 casilla 80','Enajenación de activo fijo con requisitos de ganancia ocasional.','Escritura, costo fiscal y tiempo de posesión u otro soporte específico.','ingreso','');
